   "id": "zef96e951",
   "sez": "mondo",
   "titolo": "L'Ue condanna le sanzioni Usa contro la Corte penale internazionale",
   "orig": "International Criminal Court: Statement by the High Representative on behalf of the EU following the announcement of US sanctions",
   "lead": "Il Consiglio dell'Unione europea, tramite l'Alto rappresentante, ha diffuso una dichiarazione a nome dell'Ue in risposta all'annuncio di nuove sanzioni statunitensi contro la Corte penale internazionale (Cpi). La presa di posizione arriva mentre cresce il numero di paesi che criticano la misura di Washington, tra cui l'Estonia, il cui ministero degli Esteri ha pubblicamente condannato le sanzioni. Nel frattempo restano sul tavolo le tensioni sulla politica russa: la Germania ha ribadito l'impegno a mantenere le sanzioni contro Mosca nonostante l'accordo sul diesel annunciato dagli Stati Uniti, mentre il presidente ucraino Zelensky ha definito l'intesa un modo per \"usare\" Kiev come schermo.",
   "more": [
    "La Corte penale internazionale è un tribunale permanente dell'Aja che giudica crimini di guerra, genocidio e crimini contro l'umanità; le sanzioni statunitensi contro i suoi funzionari sono già state oggetto di dispute diplomatiche negli anni passati tra Washington e la Corte."
   ],
