   "id": "z65adaf2f",
   "sez": "prima",
   "titolo": "L'uragano Isaias si rafforza a categoria 3 e punta sul Golfo degli Stati Uniti",
   "orig": "Hurricane Isaias strengthens to a major category three storm",
   "lead": "L'uragano Isaias si è rafforzato fino a diventare una tempesta di categoria 3, la prima della stagione atlantica, ed è diretto verso la costa del Golfo degli Stati Uniti, dove dovrebbe toccare terra nella notte tra venerdì e sabato. Secondo il National Hurricane Center i venti raggiungono i 120 miglia all'ora; le autorità locali hanno intensificato i preparativi mentre gli esperti segnalano rischio di inondazioni improvvise e piene fluviali localizzate lungo la costa settentrionale del Golfo. La stagione atlantica era stata finora tranquilla a causa del fenomeno El Niño, ma Isaias segna la prima formazione di rilievo del 2026.",
   "more": [
    "Gli uragani vengono classificati dalla scala Saffir-Simpson in cinque categorie in base alla velocità del vento; dalla categoria 3 in su sono considerati \"maggiori\" per il potenziale distruttivo su edifici, infrastrutture e coste."
   ],
