   "id": "z425b3264",
   "sez": "sport",
   "titolo": "Kipchoge vince la Melbourne Marathon e stabilisce il record della gara",
   "orig": "Running legend Kipchoge sets race record at Melbourne Marathon",
   "lead": "Il keniano Eliud Kipchoge ha vinto la Melbourne Marathon stabilendo il nuovo record della gara, la sua prima vittoria in una maratona dopo tre anni di assenza dai podi, l'ultima risalente a Berlino nel 2023. A 41 anni, il leggendario mezzofondista ha avuto il tempo di rallentare e salutare la folla al Melbourne Cricket Ground pur battendo il record della corsa di due secondi, dichiarando di essere felice di correre \"con la generazione Z\" e di sentirsi ancora al picco della propria forma fisica.",
   "more": [
    "Eliud Kipchoge è considerato uno dei più grandi maratoneti della storia, con numerosi record mondiali e titoli olimpici; negli ultimi anni ha intrapreso un \"World Tour\" di gare per sostenere cause benefiche a lui care."
   ],
