   "orig": "Uzbekistan Solar Panel Program Targets 3,100 Sites in $20 Million Project",
   "lead": "L'Uzbekistan sta portando avanti un programma di pannelli solari da 20 milioni di dollari destinato a raggiungere 3.100 siti nel paese: finora l'iniziativa ha fornito elettricità gratuita generata da energia solare a 1.580 abitazioni e 334 istituzioni pubbliche. Lo riferisce The Times of Central Asia.",
