   "id": "z2828e3b3",
   "sez": "spazio",
   "titolo": "Il Webb svela l'origine del fast radio burst più distante mai osservato",
   "orig": "The Most Distant FRB Tells The Story Of Its Origin",
   "lead": "Un gruppo di astronomi ha utilizzato il telescopio spaziale James Webb per studiare un fast radio burst (Frb) estremamente distante, scoprendo indizi sull'origine di questi misteriosi lampi di energia. Il segnale, composto da onde radio, avrebbe viaggiato per oltre 10 miliardi di anni attraverso circa l'80% della storia cosmica prima di raggiungere la Terra, risultando così il più distante mai registrato.",
   "more": [
    "I fast radio burst sono brevissimi ma potentissimi lampi di onde radio provenienti da galassie lontane, la cui origine resta in gran parte sconosciuta; il loro studio permette agli astronomi di sondare la materia diffusa nello spazio intergalattico e la storia dell'universo."
   ],
