   "id": "z575a91e0",
   "sez": "mondo",
   "titolo": "Abbas rinvia le elezioni palestinesi alla fine del 2027",
   "orig": "Palestinian president postpones elections until late 2027",
   "lead": "Il presidente palestinese Mahmoud Abbas ha rinviato alla fine del 2027 le elezioni legislative che aveva precedentemente promesso di tenere nel novembre 2026, citando \"ostacoli posti dalle misure israeliane\". La decisione, comunicata in una lettera alla Francia, arriva mentre Fatah, il partito di governo dell'Autorità palestinese, è attraversato da profonde divisioni interne; le elezioni presidenziali sono state fissate per settembre 2027.",
   "more": [
    "L'Autorità nazionale palestinese governa parti della Cisgiordania sotto la presidenza di Mahmoud Abbas; non si tengono elezioni generali palestinesi dal 2006, e più volte negli anni i voti promessi sono stati rinviati per ragioni politiche e di sicurezza."
   ],
