   "titolo": "In Polonia cresce l'ostilità verso le organizzazioni che aiutano i rifugiati ucraini",
   "orig": "Poland: Lifeline for Ukrainian refugees confronts donor fatigue and online abuse as anti-Ukrainian sentiment grows",
   "lead": "Una donna ucraina fuggita dalla guerra ha fondato in Polonia un'organizzazione che offre sostegno ai rifugiati ucraini, ma oggi la sua associazione deve affrontare la stanchezza dei donatori, la riduzione dei finanziamenti e una crescente ostilità online, in un contesto di sentimento anti-ucraino in aumento nel paese. Lo riferisce Deutsche Welle.",
