   "orig": "In Russian-Occupied Oleshky, Civilians Struggle to Survive as Hunger Deepens",
   "lead": "Nella città ucraina occupata dalla Russia di Oleshky, i civili rimasti faticano a sopravvivere in condizioni di fame crescente, con strade minate e forniture sempre più scarse che li costringono a rischiare la vita per procurarsi cibo o per tentare di fuggire. Lo riferisce Moscow Times.",
