   "id": "z0199500d",
   "sez": "mondo",
   "titolo": "Apre il porto di Huanggang tra Hong Kong e Shenzhen",
   "orig": "Huanggang Port opening of great significance: CE",
   "lead": "Il porto di confine di Huanggang, riqualificato tra Hong Kong e Shenzhen, apre ufficialmente lunedì con servizi di sdoganamento attivi 24 ore su 24 per passeggeri e veicoli, a partire dalle 6:30 del mattino. Il capo dell'esecutivo di Hong Kong, John Lee, ha definito l'apertura un evento di grande significato, sottolineando che riflette l'attuazione della pianificazione nazionale, mette in pratica l'innovazione istituzionale e promuove la connettività transfrontaliera all'interno della Greater Bay Area.",
   "more": [
    "La Greater Bay Area è l'area metropolitana che integra Hong Kong, Macao e diverse città del Guangdong, incluso Shenzhen; i valichi di frontiera come Huanggang sono infrastrutture chiave per facilitare gli spostamenti quotidiani di persone e merci tra le due giurisdizioni."
   ],
