   "id": "z57087de4",
   "sez": "mondo",
   "titolo": "Pillay: \"C'è un genocidio a Gaza\", riaffiora la dichiarazione del 2025",
   "orig": "Quando la Nobel per la pace Pillay disse: \"C'è un genocidio a Gaza\"",
   "lead": "Dopo l'assegnazione del Nobel per la pace 2026, torna alla luce una dichiarazione che Navi Pillay, allora alta commissaria Onu uscente, rilasciò all'Afp nel 2025: \"c'è un genocidio a Gaza\", basata su prove pubblicate dagli stessi soldati israeliani. La Repubblica intervista anche il giurista australiano che ha collaborato con Pillay al rapporto sulla Striscia, definendo il riconoscimento un premio ai \"meriti professionali\" della giurista sudafricana.",
   "more": [
    "Navi Pillay ha presieduto la commissione d'inchiesta indipendente delle Nazioni Unite sui territori palestinesi occupati, un organismo incaricato di documentare presunte violazioni dei diritti umani nel conflitto israelo-palestinese, le cui conclusioni sono state più volte contestate da Israele."
   ],
