   "orig": "12 détenus s’évadent de la prison centrale de Kangbayi à Beni",
   "lead": "Dodici detenuti sono evasi nella notte tra venerdì e sabato 10 ottobre dalla prigione centrale di Kangbayi, a Beni, nel Nord Kivu, in circostanze che secondo le prime informazioni solleverebbero interrogativi sulle condizioni di sicurezza dell'istituto penitenziario. Lo riferisce Radio Okapi.",
