   "titolo": "I leader del Pacifico denunciano i ritardi nei finanziamenti climatici in vista della Cop31",
   "orig": "Pre-COP31: Pacific leaders air frustration over climate finance delays",
   "lead": "I leader delle isole del Pacifico hanno espresso frustrazione per i lunghi tempi delle discussioni sui finanziamenti per il clima, senza vedere i risultati concreti attesi, in occasione del summit pre-Cop31 a Fiji. Nello stesso contesto, il ministro turco ospite del prossimo summit ONU ha esortato i paesi ricchi a destinare alla crisi climatica risorse ben superiori al 5% del PIL promesso dai paesi NATO per la difesa, sostenendo che la questione climatica è anche una questione di sicurezza.",
   "more": [
    "La Cop31 è la prossima conferenza delle Nazioni Unite sul clima, che si terrà in Turchia; gli stati insulari del Pacifico sono tra i paesi più esposti all'innalzamento del livello del mare e da anni chiedono fondi concreti per adattamento e mitigazione."
   ],
