   "orig": "On 'She's the Best,' Troye Sivan takes the party to unexpected places",
   "lead": "Il cantautore australiano Troye Sivan ha pubblicato il nuovo album 'She's the Best', dopo che il disco precedente gli aveva fruttato le prime nomination ai Grammy, un tour mondiale con Charli xcx e persino una parodia al Saturday Night Live. Il nuovo lavoro, secondo NPR, scava in uno strato più profondo dei suoi desideri. The Guardian lo definisce un pop star singolare e strano, che meriterebbe il multiplatino nonostante l'assenza di grandi hit, muovendosi tra shoegaze, sonorità balearic e influenze degli Smiths.",
