   "lead": "Lo scrittore britannico Philippe Sands, avvocato esperto di diritto internazionale, premiato alla Buchmesse di Francoforte, ha raccontato in un'intervista a la Repubblica come l'opera di John le Carré influenzi i suoi romanzi dedicati alle dinamiche del potere, svelando alcune delle sue battaglie professionali e letterarie. Il quotidiano olandese NRC lo ha intervistato separatamente, raccogliendo la sua riflessione sulle sfide attuali del diritto internazionale, che definisce più grandi di qualsiasi altro momento dal 1945, pur mantenendo un atteggiamento combattivo e ottimista.",
