   "lead": "Quattro astronauti sono rientrati sulla Terra giovedì dalla Stazione Spaziale Internazionale, dopo che erano stati inviati in fretta otto mesi prima per sostituire un collega malato e il suo equipaggio. L'ammaraggio della capsula SpaceX, con a bordo membri statunitensi, francesi e russi, è avvenuto nell'Oceano Pacifico, come riportano Phys.org e The Guardian, che descrivono la missione come un intervento di emergenza sanitaria.",
   "more": [
    "La Stazione Spaziale Internazionale è un laboratorio orbitante gestito in collaborazione da diverse agenzie spaziali, tra cui NASA e Roscosmos, dove gli astronauti si alternano in missioni di lunga durata per condurre esperimenti scientifici in condizioni di microgravità."
   ],
