   "lead": "Un sciopero ha colpito gli hotel Marriott e Hilton di Chicago durante il fine settimana della maratona cittadina, con il sindacato dei lavoratori che sostiene come il sistema abbia 'abbastanza soldi' per garantire condizioni migliori. Secondo Skift, sono i proprietari degli hotel, e non i marchi, a sostenere la maggior parte del costo del personale, ma le parti vedono la questione in modo opposto.",
