   "orig": "Geordie Greep Shows Cancelled Following Sexual Misconduct Allegations",
   "lead": "Il cantante Geordie Greep, ex frontman dei Black Midi, ha cancellato le tappe del suo tour a Boise, Salt Lake City, Boulder e Denver dopo essere stato accusato di cattiva condotta sessuale. L'artista, che ha negato le accuse, si era già espresso sulla vicenda durante un'esibizione a Vancouver l'8 ottobre. Lo riferisce Pitchfork.",
