   "lead": "David Koller, uno dei più noti musicisti rock della Repubblica Ceca, ha pubblicato il suo sesto album in studio, intitolato \"Nebudem se bát\" (Non avremo paura). Il disco presenta la partecipazione di diversi artisti ospiti, tra cui il celebre chitarrista Al Di Meola. Alcuni brani del nuovo lavoro sono stati trasmessi nella puntata domenicale dedicata alla musica. Lo riferisce Radio Prague International.",
