   "lead": "The BMJ critica il Leng Review, definito una grave delusione, perché non ha ridefinito con chiarezza il ruolo dei physician e anaesthesia assistant nel sistema sanitario britannico, né ha impedito che essi vedano pazienti non ancora diagnosticati, nonostante gli scandali sulla sicurezza dei pazienti già segnalati. Lo riferisce The BMJ.",
