   "lead": "Lo studio di architettura Acronym Collective Studio ha trasformato un'ex fabbrica di birra vicino a Brno in un centro comunitario, caratterizzato da una facciata curva in mattoni perforati che si affaccia sull'angolo del lotto. L'edificio, chiamato Kulturní Centrum Pivovar, si trova nella città di Velká Bíteš e ospita una biblioteca, un centro informazioni, un centro famiglie, una sala polifunzionale per la comunità e spazi creativi. Lo riferisce Dezeen.",
