   "lead": "Mahachai Residence occupa un terreno sul fiume Tha Chin, in Thailandia, dove prima si trovava il magazzino per riparazioni navali del proprietario. Lo studio Patara Architects, invece di eliminare questa storia, ha concepito l'edificio come una villa per il solo uso diurno, un luogo dove il proprietario può riposare, osservare il fiume e vederlo colorarsi d'oro al tramonto, mantenendo nella struttura e nei materiali la memoria del passato produttivo del sito.",
