   "orig": "IAEA-led Team Samples ALPS-Treated Water at Fukushima Daiichi Nuclear Power Station under Additional Measures",
   "lead": "Un team guidato dall'Agenzia internazionale per l'energia atomica ha effettuato il campionamento dell'acqua trattata con il sistema ALPS presso la centrale nucleare di Fukushima Daiichi, nell'ambito delle misure aggiuntive di controllo adottate per verificare la sicurezza degli scarichi. Lo riferisce l'Agenzia internazionale per l'energia atomica (Aiea).",
   "more": [
    "Fukushima Daiichi è la centrale nucleare giapponese danneggiata dal terremoto e dallo tsunami del 2011. Il sistema ALPS viene usato per trattare l'acqua contaminata prima del rilascio in mare, un'operazione monitorata dall'AIEA per garantirne la sicurezza."
   ],
