   "titolo": "Brasile, Lula tiene comizio a Natal mentre Flávio Bolsonaro partecipa a una moto-carovana a Rio",
   "orig": "Lula faz comício em Natal e Flávio participa de moto-carreata no Rio",
   "lead": "I candidati alla presidenza del Brasile Luiz Inácio Lula da Silva (PT) e Flávio Bolsonaro (PL) hanno avuto sabato impegni pubblici rispettivamente a Natal e a Rio de Janeiro. Nel comizio affollato nella capitale del Rio Grande do Norte, Lula ha confrontato gli investimenti fatti nel Nordest durante i governi di destra e di sinistra, sostenendo che la regione sia cambiata profondamente da quando il PT ha vinto la presidenza.",
   "more": [
    "Il Brasile si avvia al secondo turno delle elezioni presidenziali del 25 ottobre, che vedrà confrontarsi la riconferma di Lula per un quarto mandato e la candidatura di Flávio Bolsonaro, figlio dell'ex presidente Jair Bolsonaro, in rappresentanza dell'opposizione."
   ],
