   "titolo": "Madagascar, il colonnello Randrianirina chiede al fisco di intervenire contro la corruzione",
   "orig": "LUTTE CONTRE LA CORRUPTION - Le colonel Randrianirina appelle le fisc à sévir",
   "lead": "Il colonnello Randrianirina ha invitato l'amministrazione fiscale del Madagascar ad agire con fermezza nella lotta alla corruzione. Secondo 2424.mg, la direzione generale delle imposte ha lanciato la piattaforma digitale \"Torohy\", che permette ai contribuenti di segnalare gli abusi all'interno dell'amministrazione fiscale, una misura tra le diverse adottate per recuperare circa 800 milioni di dollari, pari a circa 3.000 miliardi di ariary, che il Madagascar perderebbe a causa della corruzione.",
   "more": [
    "Il Madagascar è un paese dell'Africa orientale dove la corruzione nell'amministrazione pubblica è considerata una delle principali cause di perdita di risorse statali. Piattaforme digitali di segnalazione come quella citata mirano a rendere più trasparente la riscossione fiscale."
   ],
