   "lead": "Il torneo T20 Gros Islet Battle of the Knights è continuato giovedì sera al Francis Baba Lastic Grounds, a Castries, dove i Beausejour Gladiators hanno sconfitto i Fort Rodney Sunrisers per quattro wicket, con 22 palle di anticipo. I Gladiators si sono rimessi in gioco dopo un inizio difficile in battuta. Il vicecapitano della squadra, Tyrel Chicot, premiato come man of the match, ha realizzato una prestazione completa da tutto tondo, con un punteggio personale di 50 corse decisivo per l'esito dell'incontro. Lo riferisce St. Lucia Times.",
